#!/usr/bin/env node
/**
 * Generates the human-readable production script and the WebVTT caption file
 * from the scene data, and validates the timing while doing so.
 *
 *   node scripts/generate-lesson-script.mjs
 *
 * The JSON is the single source of truth. Never hand-edit the generated files.
 */

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(root, "data/lessons/cloud-computing-models.json");
const DOC_OUT = join(root, "docs/lessons/cloud-computing-models.md");
const VTT_OUT = join(root, "public/courses/aws-cloud-practitioner/cloud-computing-models.vtt");

const script = JSON.parse(readFileSync(SOURCE, "utf8"));

/* ---------------------------------------------------------------- validate */

const problems = [];
let cursor = 0;
let spokenWords = 0;
let spokenSeconds = 0;
let silentSeconds = 0;
let sceneCount = 0;

for (const section of script.sections) {
  if (section.startSeconds !== cursor) {
    problems.push(
      `Section ${section.number} starts at ${section.startSeconds}s, expected ${cursor}s`,
    );
  }
  let sceneCursor = section.startSeconds;
  let sum = 0;
  for (const scene of section.scenes) {
    if (scene.startSeconds !== sceneCursor) {
      problems.push(
        `Scene ${scene.id} starts at ${scene.startSeconds}s, expected ${sceneCursor}s`,
      );
    }
    const words = scene.narration.trim()
      ? scene.narration.trim().split(/\s+/).length
      : 0;
    if (words) {
      spokenWords += words;
      spokenSeconds += scene.durationSeconds;
      const wpm = words / (scene.durationSeconds / 60);
      if (wpm > 145) {
        problems.push(`Scene ${scene.id} needs ${wpm.toFixed(0)} wpm — too fast to read`);
      }
    } else {
      silentSeconds += scene.durationSeconds;
    }
    sceneCursor += scene.durationSeconds;
    sum += scene.durationSeconds;
    sceneCount += 1;
  }
  if (sum !== section.durationSeconds) {
    problems.push(
      `Section ${section.number} scenes total ${sum}s but the section declares ${section.durationSeconds}s`,
    );
  }
  cursor += section.durationSeconds;
}

if (cursor !== script.totalDurationSeconds) {
  problems.push(
    `Sections total ${cursor}s but the lesson declares ${script.totalDurationSeconds}s`,
  );
}

if (problems.length) {
  console.error("Timing validation failed:\n" + problems.map((p) => `  - ${p}`).join("\n"));
  process.exit(1);
}

/* ----------------------------------------------------------------- helpers */

const tc = (s) =>
  `${Math.floor(s / 60)
    .toString()
    .padStart(2, "0")}:${Math.floor(s % 60)
    .toString()
    .padStart(2, "0")}`;

const vtt = (s) =>
  `00:${Math.floor(s / 60)
    .toString()
    .padStart(2, "0")}:${(s % 60).toFixed(3).padStart(6, "0")}`;

/* ------------------------------------------------------------- markdown doc */

const out = [];
const w = (line = "") => out.push(line);

w(`# ${script.lessonTitle} — production script`);
w();
w(`> Generated from \`data/lessons/cloud-computing-models.json\` by`);
w(`> \`scripts/generate-lesson-script.mjs\`. Do not edit this file by hand —`);
w(`> edit the JSON and regenerate.`);
w();
w(`**${script.subtitle}**`);
w();
w(`| | |`);
w(`|---|---|`);
w(`| LearnHub course | \`${script.courseId}\` — AWS Cloud Practitioner |`);
w(`| Module | \`${script.moduleId}\` — ${script.moduleTitle} |`);
w(`| Lesson | \`${script.lessonId}\` — ${script.lessonTitle} |`);
w(`| Runtime | **${tc(script.totalDurationSeconds)}** (${script.totalDurationSeconds}s) |`);
w(`| Sections | ${script.sections.length} |`);
w(`| Scenes | ${sceneCount} |`);
w(`| Narration | ${spokenWords} words · ${(spokenWords / (spokenSeconds / 60)).toFixed(0)} wpm delivery pace |`);
w(`| Silent beats | ${silentSeconds}s (quiz think time) |`);
w(`| Audience | ${script.audience} |`);
w();

w(`## Render specification`);
w();
w(`| Setting | Value |`);
w(`|---|---|`);
w(`| Resolution | ${script.renderSpec.resolution} @ ${script.renderSpec.fps}fps (${script.renderSpec.aspectRatio}) |`);
w(`| Safe area | ${script.renderSpec.safeAreaPaddingPx}px padding |`);
w(`| Background music | ${script.renderSpec.backgroundMusic} |`);
w(`| Captions | ${script.renderSpec.captions.format}, generated from narration |`);
w();
w(`### Palette — ${script.renderSpec.theme.name}`);
w();
w(`| Token | Hex |`);
w(`|---|---|`);
for (const [k, v] of Object.entries(script.renderSpec.theme.colors)) {
  w(`| \`${k}\` | \`${v}\` |`);
}
w();
w(`### Typography`);
w();
for (const [k, v] of Object.entries(script.renderSpec.theme.fonts)) {
  w(`- **${k}** — ${v}`);
}
w();
w(`### Motion`);
w();
for (const [k, v] of Object.entries(script.renderSpec.theme.motion)) {
  w(`- **${k}** — ${v}`);
}
w();
w(`### Voice-over direction`);
w();
w(`**Style.** ${script.renderSpec.voiceOver.style}`);
w();
w(`**Pace.** ${script.renderSpec.voiceOver.pace}`);
w();
for (const d of script.renderSpec.voiceOver.direction) w(`- ${d}`);
w();
w(`**Pronunciation.**`);
w();
for (const [k, v] of Object.entries(script.renderSpec.voiceOver.pronunciation)) {
  w(`- \`${k}\` — ${v}`);
}
w();

w(`## Running order`);
w();
w(`| # | Section | In | Out | Duration | Scenes |`);
w(`|---|---|---|---|---|---|`);
for (const s of script.sections) {
  w(
    `| ${s.number} | ${s.title} | ${tc(s.startSeconds)} | ${tc(
      s.startSeconds + s.durationSeconds,
    )} | ${s.durationSeconds}s | ${s.scenes.length} |`,
  );
}
w();
w(`---`);
w();

for (const section of script.sections) {
  w(
    `## ${section.number}. ${section.title}`,
  );
  w();
  w(
    `\`${tc(section.startSeconds)} – ${tc(
      section.startSeconds + section.durationSeconds,
    )}\` · ${section.durationSeconds}s · ${section.scenes.length} scenes`,
  );
  w();
  if (section.note) {
    w(`> ${section.note}`);
    w();
  }

  for (const scene of section.scenes) {
    w(
      `### \`${scene.id}\` · ${tc(scene.startSeconds)} – ${tc(
        scene.startSeconds + scene.durationSeconds,
      )} · ${scene.durationSeconds}s`,
    );
    w();

    const os = scene.onScreen ?? {};
    if (os.heading) w(`**On screen — heading:** ${os.heading}  `);
    if (os.subheading) w(`**On screen — subheading:** ${os.subheading}  `);
    if (os.callout) w(`**On screen — callout:** ${os.callout}  `);
    if (os.bullets?.length) {
      w();
      w(`**On screen — text:**`);
      w();
      for (const b of os.bullets) w(`- ${b}`);
    }
    if (os.keyTerm) {
      w();
      w(`**Key term card:** **${os.keyTerm.term}** — ${os.keyTerm.definition}`);
    }
    w();
    w(`**Visual:** ${scene.visual}`);
    w();
    w(`**Animation:** ${scene.animation}`);
    w();

    if (scene.diagram?.type === "responsibility-stack") {
      const d = scene.diagram;
      w(`**Diagram — responsibility stack** (active: ${d.activeColumns.join(", ")})`);
      w();
      if (d.layerOrderTopToBottom) {
        w(`Layers, top to bottom: ${d.layerOrderTopToBottom.join(" · ")}`);
        w();
      }
      for (const col of d.columns) {
        w(`- **${col.label}** (\`${col.headerColor}\`)`);
        w(
          `  - Customer manages: ${
            col.customerManaged.length ? col.customerManaged.join(", ") : "— nothing —"
          }`,
        );
        w(
          `  - Provider manages: ${
            col.providerManaged.length ? col.providerManaged.join(", ") : "— nothing —"
          }`,
        );
        if (col.customerFocus) w(`  - Customer focus: ${col.customerFocus}`);
      }
      w();
    }

    if (scene.diagram?.type === "comparison-table") {
      const d = scene.diagram;
      w(`**Diagram — animated comparison table**`);
      w();
      w(`| ${d.columns.join(" | ")} |`);
      w(`|${d.columns.map(() => "---").join("|")}|`);
      for (const r of d.rows) {
        w(`| **${r.model}** | ${r.control} | ${r.management} |`);
      }
      w();
    }

    if (scene.quiz) {
      const q = scene.quiz;
      w(`**Quiz — \`${q.questionId}\` · phase: ${q.phase}**`);
      w();
      if (q.options?.length) {
        q.options.forEach((opt, i) => {
          const letter = String.fromCharCode(65 + i);
          const mark = i === q.correctIndex ? " ✅" : "";
          w(`- ${letter}. ${opt}${mark}`);
        });
        w();
      }
      if (q.explanation) {
        w(`Explanation: ${q.explanation}`);
        w();
      }
    }

    if (scene.narration.trim()) {
      w(`**Narration**`);
      w();
      w(`> ${scene.narration}`);
    } else {
      w(`**Narration** — *silent beat, no voice-over.*`);
    }
    w();
  }
  w(`---`);
  w();
}

w(`## Knowledge check answer key`);
w();
w(`| # | Question | Answer |`);
w(`|---|---|---|`);
let qn = 0;
for (const section of script.sections) {
  for (const scene of section.scenes) {
    if (scene.quiz?.phase === "read") {
      qn += 1;
      const q = scene.quiz;
      const letter = String.fromCharCode(65 + q.correctIndex);
      w(`| ${qn} | ${q.question} | **${letter}** — ${q.options[q.correctIndex]} |`);
    }
  }
}
w();

writeFileSync(DOC_OUT, out.join("\n"));

/* ------------------------------------------------------------------- webvtt */

const cues = [];
let n = 0;
for (const section of script.sections) {
  for (const scene of section.scenes) {
    if (!scene.narration.trim()) continue;
    n += 1;
    cues.push(
      `${n}\n${vtt(scene.startSeconds)} --> ${vtt(
        scene.startSeconds + scene.durationSeconds,
      )}\n${scene.narration}`,
    );
  }
}
mkdirSync(dirname(VTT_OUT), { recursive: true });
writeFileSync(VTT_OUT, `WEBVTT\n\n${cues.join("\n\n")}\n`);

console.log(`Timing OK — ${tc(script.totalDurationSeconds)}, ${sceneCount} scenes.`);
console.log(`Wrote ${DOC_OUT}`);
console.log(`Wrote ${VTT_OUT} (${n} caption cues)`);
